        //==============================================================================
        double getMaxFrequency() const
        {
            return 192000.0;
        }

        void initialise (int32_t sessionID, double frequency)
        {
            if (frequency > getMaxFrequency()) throw std::runtime_error ("frequency out of range");
            initSessionID = sessionID;
            initFrequency = frequency;
            reset();
        }

        void reset()
        {
            std::memset (reinterpret_cast<char*> (&cmajState), 0, sizeof (cmajState));
            int32_t processorID = 0;
            _initialise (cmajState, processorID, initSessionID, initFrequency);
        }

        void advance (int32_t frames)
        {
            cmajIO.out.clear (static_cast<SizeType> (frames));
            _advance (cmajState, cmajIO, frames);
        }

        void copyOutputValue (EndpointHandle endpointHandle, void* dest)
        {
            (void) endpointHandle; (void) dest;

            throw std::runtime_error ("Unknown value endpointHandle:" + std::to_string (endpointHandle));
        }

        void copyOutputFrames (EndpointHandle endpointHandle, void* dest, uint32_t numFramesToCopy)
        {
            if (endpointHandle == 7648) { std::memcpy (reinterpret_cast<char*> (dest), std::addressof (cmajIO.out), 8 * numFramesToCopy); std::memset (reinterpret_cast<char*> (std::addressof (cmajIO.out)), 0, 8 * numFramesToCopy); return; }
            throw std::runtime_error ("Unknown stream endpointHandle:" + std::to_string (endpointHandle));
        }

        uint32_t getNumOutputEvents (EndpointHandle endpointHandle)
        {
            if (endpointHandle == 7649) return (uint32_t) cmajState.insDump_eventCount;
            if (endpointHandle == 7650) return (uint32_t) cmajState.insPos_eventCount;
            if (endpointHandle == 7651) return (uint32_t) cmajState.fxViz_eventCount;
            if (endpointHandle == 7652) return (uint32_t) cmajState.seqPos_eventCount;
            throw std::runtime_error ("Unknown event endpointHandle:" + std::to_string (endpointHandle));
            return {};
        }

        void resetOutputEventCount (EndpointHandle endpointHandle)
        {
            if (endpointHandle == 7649) { cmajState.insDump_eventCount = 0; return; }
            if (endpointHandle == 7650) { cmajState.insPos_eventCount = 0; return; }
            if (endpointHandle == 7651) { cmajState.fxViz_eventCount = 0; return; }
            if (endpointHandle == 7652) { cmajState.seqPos_eventCount = 0; return; }
        }

        uint32_t getOutputEventType (EndpointHandle endpointHandle, uint32_t index)
        {
            if (endpointHandle == 7649) return (uint32_t) cmajState.insDump[(IndexType) index].type;
            if (endpointHandle == 7650) return (uint32_t) cmajState.insPos[(IndexType) index].type;
            if (endpointHandle == 7651) return (uint32_t) cmajState.fxViz[(IndexType) index].type;
            if (endpointHandle == 7652) return (uint32_t) cmajState.seqPos[(IndexType) index].type;
            throw std::runtime_error ("Unknown event endpointHandle:" + std::to_string (endpointHandle));
            return {};
        }

        static uint32_t getOutputEventDataSize (EndpointHandle endpointHandle, uint32_t typeIndex)
        {
            (void) endpointHandle; (void) typeIndex;

            if (endpointHandle == 7649 && typeIndex == 0) return 4;
            if (endpointHandle == 7650 && typeIndex == 0) return 4;
            if (endpointHandle == 7651 && typeIndex == 0) return 4;
            if (endpointHandle == 7652 && typeIndex == 0) return 4;
            throw std::runtime_error ("Unknown event endpointHandle:" + std::to_string (endpointHandle));
            return 0;
        }

        uint32_t readOutputEvent (EndpointHandle endpointHandle, uint32_t index, unsigned char* dest)
        {
            if (endpointHandle == 7649)
            {
                auto& event = cmajState.insDump[(IndexType) index];
                if (event.type == 0)
                {
                    memcpy (dest, std::addressof (event.value_0), 4);
                    dest += 4;
                    return (uint32_t) event.frame;
                }
            }
            if (endpointHandle == 7650)
            {
                auto& event = cmajState.insPos[(IndexType) index];
                if (event.type == 0)
                {
                    memcpy (dest, std::addressof (event.value_0), 4);
                    dest += 4;
                    return (uint32_t) event.frame;
                }
            }
            if (endpointHandle == 7651)
            {
                auto& event = cmajState.fxViz[(IndexType) index];
                if (event.type == 0)
                {
                    memcpy (dest, std::addressof (event.value_0), 4);
                    dest += 4;
                    return (uint32_t) event.frame;
                }
            }
            if (endpointHandle == 7652)
            {
                auto& event = cmajState.seqPos[(IndexType) index];
                if (event.type == 0)
                {
                    memcpy (dest, std::addressof (event.value_0), 4);
                    dest += 4;
                    return (uint32_t) event.frame;
                }
            }

            throw std::runtime_error ("Unknown event endpointHandle:" + std::to_string (endpointHandle));
            return {};
        }

